    handleDragOver: function handleDragOver(e) {
      // e.dataTransfer.dropEffect="move";//在dragenter中针对放置目标来设置!
      e.dataTransfer.dropEffect = "move";
    },
    handleDragEnter: function handleDragEnter(e, item) {
      // 为需要移动的元素设置dragstart事件
      e.dataTransfer.effectAllowed = "move";
      if (item === this.dragging) {
        return;
      }
      var newItems = _toConsumableArray(this.formValidate.slider_image);
      var src = newItems.indexOf(this.dragging);
      var dst = newItems.indexOf(item);
      newItems.splice.apply(newItems, [dst, 0].concat(_toConsumableArray(newItems.splice(src, 1))));
      this.formValidate.slider_image = newItems;
    },
    // 添加自定义弹窗
    addCustomDialog: function addCustomDialog(editorId) {
      window.UE.registerUI("test-dialog", function (editor, uiName) {
        var dialog = new window.UE.ui.Dialog({
          iframeUrl: "/admin/widget.images/index.html?fodder=dialog",
          editor: editor,
          name: uiName,
          title: "上传图片",
          cssRules: "width:1200px;height:500px;padding:20px;"
        });
        this.dialog = dialog;
        var btn = new window.UE.ui.Button({
          name: "dialog-button",
          title: "上传图片",
          cssRules: "background-image: url(../../../assets/images/icons.png);background-position: -726px -77px;",
          onclick: function onclick() {
            dialog.render();
            dialog.open();
          }
        });
        return btn;
      }, 37);
    }
  }
